// Every command the frontend may invoke is listed here; tauri-plugin generates
// the allow/deny permissions for them into permissions/autogenerated/, which is
// committed. permissions/default.toml is hand-written.
//
// No entitlement is written from here. The `com.apple.developer.applesignin`
// entitlement is added by CI when the feature is turned on (docs/platform/713):
// a build script only runs when this crate is recompiled, and a cached crate
// never writes into the freshly generated gen/apple (docs/pitfall 157).
const COMMANDS: &[&str] = &["is_available", "sign_in"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).ios_path("ios").build();
}
